import React, { useState } from 'react';
import { Routes, Route, Link } from 'react-router-dom';
import News from './pages/News';
import About from './pages/About';
import Contact from './pages/Contact';
import Products from './pages/Products';

function App() {
  const [lang, setLang] = useState('ru');

  const text = {
    ru: {
      news: 'Новости',
      about: 'Об авторе',
      contact: 'Обратная связь',
      products: 'Продукты и услуги',
      logo: 'Сайт педагога',
      footer: 'Контакты: +7 908 517 50 43'
    },
    en: {
      news: 'News',
      about: 'About author',
      contact: 'Contact',
      products: 'Products and services',
      logo: 'Teacher website',
      footer: 'Contacts: +7 908 517 50 43'
    }
  };

  return (
    <div className="container">
      <header>
        <h2>{text[lang].logo}</h2>
      </header>

      <main>
        <section>
          <nav>
            <Link to="/">{text[lang].news}</Link>
            <Link to="/about">{text[lang].about}</Link>
            <Link to="/contact">{text[lang].contact}</Link>
            <Link to="/products">{text[lang].products}</Link>
          </nav>

          <button onClick={() => setLang(lang === 'ru' ? 'en' : 'ru')}>
            {lang === 'ru' ? 'EN' : 'RU'}
          </button>
        </section>

        <article>
          <Routes>
            <Route path="/" element={<News lang={lang} />} />
            <Route path="/about" element={<About lang={lang} />} />
            <Route path="/contact" element={<Contact lang={lang} />} />
            <Route path="/products" element={<Products lang={lang} />} />
          </Routes>
        </article>

        <aside>
          <h3>Теги</h3>
          <p>React</p>
          <p>HTML</p>
          <p>CSS</p>
        </aside>
      </main>

      <footer>
        <p>{text[lang].footer}</p>
      </footer>
    </div>
  );
}

export default App;
